// ============================================================================
// XUẤT BÁO CÁO WORD THEO CHUẨN NGHỊ ĐỊNH 06
// ============================================================================

const TEMPLATE_BASE64 = "";

function base64ToArrayBuffer(base64) {
    var binary_string = window.atob(base64);
    var len = binary_string.length;
    var bytes = new Uint8Array(len);
    for (var i = 0; i < len; i++) {
        bytes[i] = binary_string.charCodeAt(i);
    }
    return bytes.buffer;
}

const WordExport = {
  exportReport(companyInfo, calcResults, reportYear) {
    if (!companyInfo || !companyInfo.name) {
      alert("Vui lòng vào phần 'Thiết lập' điền thông tin Công ty trước khi xuất báo cáo!");
      return;
    }

    try {
      const content = base64ToArrayBuffer(TEMPLATE_BASE64);
      const zip = new PizZip(content);
      const doc = new window.docxtemplater(zip, {
        paragraphLoop: true,
        linebreaks: true,
      });

      
      // --- XỬ LÝ CHI TIẾT THIẾT BỊ TỪ BẢNG HOẠT ĐỘNG ---

      let activities = [];
      if (window.__exportActivitiesOverride) {
          activities = window.__exportActivitiesOverride;
      } else {
          const userStr = localStorage.getItem('gs_current_user') || 'guest';
          const branchSelect = document.getElementById('branch-selector');
          if (branchSelect) {
              const branchName = branchSelect.value;
              const branchKey = branchName.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, '_').replace(/[^a-z0-9_]/g, '');
              const storageKey = `gs_data_${userStr}_${branchKey}_activity`;
              activities = JSON.parse(localStorage.getItem(storageKey)) || [];
          } else {
              activities = JSON.parse(localStorage.getItem('gs_v2_activity_main')) || [];
          }
          if (activities.length === 0) {
              const old = JSON.parse(localStorage.getItem('gs_v2_activity_main')) || [];
              if (old.length > 0) activities = old;
          }
      }


      const scope1_stationary = [];
      const scope1_mobile = [];
      const scope2_grid = [];
      const scope1_fugitive = [];   // Phát thải thất thoát (môi chất lạnh, SF6, Halon)
      const scope1_wastewater = []; // Nước thải sinh hoạt (TOW)
      
      const tbl_317 = []; // AD Uncertainty
      const tbl_318 = []; // EF Uncertainty

      
      let sumGHG = 0;
      let sumSquares = 0;

      activities.forEach((act, index) => {
        const amount = parseFloat(act.amount) || 0;
        if (amount <= 0) return;

        let efObj = null;
        if (typeof EF_MASTER !== 'undefined' && EF_MASTER.VN) {
            if (act.fuelId) {
                efObj = EF_MASTER.VN.fuels[act.fuelId] || (EF_MASTER.VN.electricity && EF_MASTER.VN.electricity[act.fuelId]);
            }
            if (!efObj && act.efName) {
                const fuels = Object.values(EF_MASTER.VN.fuels || {});
                efObj = fuels.find(f => f.name === act.efName);
                if (!efObj && EF_MASTER.VN.electricity) {
                    const elecs = Object.values(EF_MASTER.VN.electricity);
                    efObj = elecs.find(e => e.name === act.efName);
                }
            }
        }

        const type = act.sourceType || '';
        const group = act.sourceGroup || '';
        const eqStr = (act.sourceName || '').toLowerCase();
        const isScope2 = (type === 'Điện mua vào' || type === 'Năng lượng mua vào (hơi, nhiệt)' || act.category === 'Phạm vi 2');
        const isFugitive = (type === 'Phát thải thất thoát') && !!act.refName;
        const isWastewater = (type === 'Phát thải thất thoát' || type === 'Nước thải') && 
            (eqStr.includes('tự hoại') || eqStr.includes('hiếu khí') || eqStr.includes('kỵ khí') || 
             eqStr.includes('nước thải') || eqStr.includes('bùn') || eqStr.includes('biogas') || eqStr.includes('aerotank'));


        const t_co2e = parseFloat(act.co2e) ? parseFloat(act.co2e) / 1000 : (amount * (act.finalFactor || (efObj ? efObj.factor : 0))) / 1000;
        
        sumGHG += t_co2e;

        // Uncertainty Mapping
        let u_ad = 0.10; // Default 10%
        if (act.measure === 'Đo liên tục') u_ad = 0.02;
        else if (act.reliability === 'Bằng chứng kế toán / Hóa đơn' || act.reliability === 'Những người có bằng chứng cải chính nội bộ hoặc visa kế toán') u_ad = 0.05;
        else if (act.measure === 'Ước tính kế toán tài chính' || act.reliability === 'Sử dụng dữ liệu thứ cấp hoặc tham khảo') u_ad = 0.10;
        else if (act.reliability === 'Không có bằng chứng rõ ràng' || act.reliability === 'Không có chứng từ rõ ràng') u_ad = 0.20;

        const ipcc_code = efObj ? (efObj.ipcc_code || "N/A") : "N/A";
        const u_ef_co2 = efObj && efObj.u_ef_co2 ? efObj.u_ef_co2 / 100 : 0.05;
        const u_ef_ch4 = efObj && efObj.u_ef_ch4 ? efObj.u_ef_ch4 / 100 : 0.50;
        const u_ef_n2o = efObj && efObj.u_ef_n2o ? efObj.u_ef_n2o / 100 : 0.50;
        const u_ef_hfc = 0.30; // default for HFCs
        
        // Add to tbl_317 (Activity Data)
        tbl_317.push({
            ipcc: ipcc_code,
            name: act.sourceName || "Thiết bị",
            gas: type === 'Phát thải thất thoát' ? 'HFCs' : 'CO2, CH4, N2O',
            u_ad: (u_ad * 100).toFixed(2).replace('.', ','),
            ref: 'IPCC 2006 / 2019'
        });
        
        // Add to tbl_318 (Emission Factor)
        if (type === 'Phát thải thất thoát') {
            tbl_318.push({
                ipcc: ipcc_code,
                name: act.sourceName,
                gas: 'HFCs',
                u_ef: (u_ef_hfc * 100).toFixed(2).replace('.', ','),
                ref: 'IPCC 2019'
            });
            const uSource = Math.sqrt(Math.pow(u_ad, 2) + Math.pow(u_ef_hfc, 2));
            sumSquares += Math.pow(t_co2e * uSource, 2);
        } else {
            tbl_318.push({
                ipcc: ipcc_code,
                name: act.sourceName,
                gas: 'CO2',
                u_ef: (u_ef_co2 * 100).toFixed(2).replace('.', ','),
                ref: 'IPCC 2006'
            });
            tbl_318.push({
                ipcc: ipcc_code,
                name: act.sourceName,
                gas: 'CH4',
                u_ef: (u_ef_ch4 * 100).toFixed(2).replace('.', ','),
                ref: 'IPCC 2006'
            });
            tbl_318.push({
                ipcc: ipcc_code,
                name: act.sourceName,
                gas: 'N2O',
                u_ef: (u_ef_n2o * 100).toFixed(2).replace('.', ','),
                ref: 'IPCC 2006'
            });
            const uSource = Math.sqrt(Math.pow(u_ad, 2) + Math.pow(u_ef_co2, 2)); // Simplified combination
            sumSquares += Math.pow(t_co2e * uSource, 2);
        }

        if (isScope2) {
            scope2_grid.push({
                name: act.sourceName || "Khu vực",
                consumption_kwh: amount.toLocaleString('vi-VN'),
                ef_grid: act.finalFactor ? act.finalFactor.toString().replace('.', ',') : (efObj ? (efObj.factor || 0).toString().replace('.', ',') : '-'),
                t_co2e: t_co2e.toFixed(2).replace('.', ',')
            });
        } else if (isFugitive) {
            // Bảng phát thải thất thoát (môi chất lạnh, SF6, Halon)
            const gwp = act.finalFactor || (efObj ? (efObj.gwp || efObj.factor || 0) : 0);
            scope1_fugitive.push({
                name:    act.sourceName || "Thiết bị",
                ref_gas: act.refName || act.efName || "Chưa xác định",
                gwp:     gwp > 0 ? gwp.toLocaleString('vi-VN') : '-',
                unit:    act.unit || 'kg',
                amount:  amount.toLocaleString('vi-VN'),
                t_co2e:  t_co2e.toFixed(2).replace('.', ',')
            });
        } else if (isWastewater) {
            // Bảng nước thải: [(TOW - S) × EF - R]
            const wwS = parseFloat(act.wwS) || 0;
            const wwR = parseFloat(act.wwR) || 0;
            scope1_wastewater.push({
                name:   act.sourceName || "Hệ thống xử lý",
                tow:    amount.toLocaleString('vi-VN'),
                s:      wwS > 0 ? wwS.toLocaleString('vi-VN') : '0',
                r:      wwR > 0 ? wwR.toLocaleString('vi-VN') : '0',
                ef_ww:  act.finalFactor ? act.finalFactor.toString().replace('.', ',') : '-',
                t_co2e: t_co2e.toFixed(2).replace('.', ',')
            });
        } else {
            // Đốt cháy (cố định hoặc động) — IPCC Eq 2.1
            const density = efObj ? (efObj.density || 1) : 1;
            const ncv = efObj ? (efObj.ncv || 0) : 0;
            const consumption_gg = (amount * density) / 1000000;
            const tj = consumption_gg * ncv;
            const ef_co2_tj = efObj ? (efObj.ef_co2_tj || 0) : 0;
            const ef_ch4_tj = efObj ? (efObj.ef_ch4_tj || 0) : 0;
            const ef_n2o_tj = efObj ? (efObj.ef_n2o_tj || 0) : 0;
            const t_co2 = (tj * ef_co2_tj) / 1000;
            const t_ch4 = (tj * ef_ch4_tj) / 1000;
            const t_n2o = (tj * ef_n2o_tj) / 1000;
            const rowData = {
                name: act.sourceName || "Thiết bị",
                fuel: efObj ? efObj.name : (act.efName || act.sourceType || "Chưa xác định"),
                unit: act.unit || "N/A",
                consumption_original: amount.toLocaleString('vi-VN'),
                density: density !== 1 ? density.toString().replace('.', ',') : '-',
                consumption_gg: consumption_gg > 0 ? consumption_gg.toFixed(5).replace('.', ',') : '-',
                ncv: ncv > 0 ? ncv.toString().replace('.', ',') : '-',
                tj: tj > 0 ? tj.toFixed(4).replace('.', ',') : '-',
                ef_co2: ef_co2_tj > 0 ? ef_co2_tj.toLocaleString('vi-VN') : '-',
                t_co2: t_co2 > 0 ? t_co2.toFixed(2).replace('.', ',') : '-',
                ef_ch4: ef_ch4_tj > 0 ? ef_ch4_tj.toLocaleString('vi-VN') : '-',
                t_ch4: t_ch4 > 0 ? t_ch4.toFixed(4).replace('.', ',') : '-',
                ef_n2o: ef_n2o_tj > 0 ? ef_n2o_tj.toLocaleString('vi-VN') : '-',
                t_n2o: t_n2o > 0 ? t_n2o.toFixed(5).replace('.', ',') : '-',
                t_co2e: t_co2e.toFixed(2).replace('.', ',')
            };
            if (type === 'Đốt cháy động' || group === 'Nguồn đốt di động') {
                scope1_mobile.push(rowData);
            } else {
                scope1_stationary.push(rowData);
            }
        }
      });      
      const total_uncertainty = sumGHG > 0 ? Math.sqrt(sumSquares) / sumGHG : 0;
      // Tạo object Dữ liệu (Mapping tags)
      // Số liệu phát thải
      const scope1_combustion = scope1_stationary.concat(scope1_mobile);
        
        scope1_wastewater.forEach(ww => {
            ww.ch4_kg = (parseFloat(ww.t_co2e.replace(',', '.')) * 1000 / 28).toFixed(2).replace('.', ',');
            ww.gwp = '28';
        });

        const data = {
            company_name: companyInfo.name,
            tax: companyInfo.tax || "...",
            license: companyInfo.license || "...",
            founded_year: companyInfo.foundedYear || "...",
            address: companyInfo.address || "...",
            manager_agency: companyInfo.managerAgency || "...",
            gps: companyInfo.gps || "...",
            phone: companyInfo.phone || "...",
            email: companyInfo.email || "...",
            website: companyInfo.website || "...",
            industry: companyInfo.industry || "...",

            rep_name: companyInfo.repName || "...",
            rep_title: companyInfo.repTitle || "...",
            rep_phone: companyInfo.repPhone || "...",
            rep_email: companyInfo.repEmail || "...",

            desc_boundary: companyInfo.descBoundary || "",
            desc_process: companyInfo.descProcess || "",
            desc_waste: companyInfo.descWaste || "",

            total_emissions: calcResults.total ? calcResults.total.toFixed(2) : "0",
            scope1_total: calcResults.scope1 ? calcResults.scope1.toFixed(2) : "0",
            scope2_total: calcResults.scope2 ? calcResults.scope2.toFixed(2) : "0",
            
            reportYear: reportYear || "2026",
            scope1_stationary: scope1_stationary.map((x, i) => ({...x, i: i+1})),
            scope1_mobile: scope1_mobile.map((x, i) => ({...x, i: i+1, vehicle_info: 'N/A', desc: 'Sử dụng nhiên liệu'})),
            scope1_fugitive: scope1_fugitive.map((x, i) => ({...x, i: i+1, location: 'N/A', start_date: 'N/A', capacity: '-', time: 'N/A'})),
            scope1_wastewater: scope1_wastewater,
            scope1_combustion: scope1_combustion,
            scope2_grid: scope2_grid,
            tbl_317: tbl_317,
            tbl_318: tbl_318,
            uncertainty_pct: (total_uncertainty * 100).toFixed(2).replace('.', ',')
        };

      doc.render(data);

      const out = doc.getZip().generate({
        type: "blob",
        mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      });

      saveAs(out, `Bao_Cao_KNK_${companyInfo.name}_${reportYear}.docx`);
      
    } catch (error) {
      console.error("Lỗi khi tạo file Word:", error);
      alert("Lỗi tạo file Word: " + error.message + "\n" + (error.properties ? JSON.stringify(error.properties.errors) : ""));
    }
  }
};

